import * as F from './formulas.js?v=6.0.0-r1';
const bi=(ru,en)=>({ru,en});
const n=x=>Number(x);
const num=(id,ru,en,unit,min,max,def,profileKey,step='any')=>({id,type:'number',label:bi(ru,en),unit,min,max,default:def,profileKey,step,required:true});
const text=(id,ru,en,def,placeholder='')=>({id,type:'text',label:bi(ru,en),default:def,placeholder,required:true});
const sel=(id,ru,en,options,def,profileKey)=>({id,type:'select',label:bi(ru,en),options,default:def,profileKey,required:true});
const time=(id,ru,en,def)=>({id,type:'time',label:bi(ru,en),default:def,required:true});
const sex=()=>sel('sex','Пол','Sex',[{value:'male',label:bi('Мужской','Male')},{value:'female',label:bi('Женский','Female')}],'male','sex');
const result=(primary,unit,interpretation,limitation,action,formula,workings=[])=>({primary,unit,secondary:[],interpretation:bi(...interpretation),confidence:bi('Смотрите тип метода и силу основания выше.','See method type and evidence strength above.'),limitation:bi(...limitation),action:bi(...action),assumptions:[bi(...formula)],workings});
const make=(id,category,title,description,methodType,evidenceStrength,sources,fields,calculate,featured=false,keywords=[])=>({id,category,title:bi(...title),description:bi(...description),methodType,evidenceStrength,sources,fields,calculate,featured,keywords});
const estLimit=['Это оценка по ограниченному набору входов; индивидуальная ошибка может быть существенной.','This is an estimate from limited inputs; individual error may be material.'];
const mathLimit=['Результат точен в рамках введённых данных и выбранной арифметики.','The result is exact only within the supplied inputs and arithmetic.'];
const scenarioLimit=['Сценарий не предсказывает индивидуальный результат и зависит от допущений.','This scenario does not predict an individual outcome and depends on assumptions.'];
const checkTrend=['Используйте как контекст и отслеживайте динамику, а не одиночное число.','Use it as context and track trends rather than a single number.'];
const minsToClock=m=>{const h=Math.floor(m/60),s=Math.round((m-h*60)*60);return `${h}:${String(s).padStart(2,'0')}`};

